<template><div v-if="sale" class="space-y-4"><div class="page-head"><div><RouterLink to="/sales" class="text-[11px] font-bold text-indigo-600">← Sales</RouterLink><h1 class="mt-2">{{sale.sale_number}}</h1><p>{{sale.client?.name||'Walk-in customer'}} · {{formatDisplayDate(sale.sale_date)}}</p></div><div class="action-row"><RouterLink v-if="sale.client_id" :to="`/clients/${sale.client_id}`" class="btn btn-soft">View client</RouterLink><RouterLink v-if="sale.invoice_id || sale.invoice?.id" :to="`/invoices/${sale.invoice_id || sale.invoice.id}`" class="btn btn-primary">View invoice</RouterLink><button v-if="sale.status!=='cancelled'" class="btn btn-danger" @click="voidSale">Void sale</button></div></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-4"><div class="card metric"><div class="metric-label">Total</div><div class="metric-value mt-2">{{money(sale.total)}}</div></div><div class="card metric"><div class="metric-label">Payment</div><div class="metric-value mt-2 text-lg capitalize">{{sale.payment_status}}</div></div><div class="card metric"><div class="metric-label">Status</div><div class="mt-3"><StatusBadge :value="sale.status"/></div></div><div class="card metric"><div class="metric-label">Invoice</div><div class="metric-value mt-2 text-lg">{{sale.invoice?.invoice_number||'—'}}</div></div></div><div class="card overflow-hidden"><div class="px-5 py-4 border-b border-slate-100 dark:border-slate-800"><h2 class="text-sm font-extrabold">Sale items</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Discount</th><th class="text-right">Amount</th></tr></thead><tbody><tr v-for="i in sale.items||[]" :key="i.id"><td>{{i.product?.name||'Product'}}</td><td>{{i.quantity}}</td><td>{{money(i.unit_price)}}</td><td>{{money(i.discount)}}</td><td class="text-right font-bold">{{money(i.total)}}</td></tr><tr v-if="!(sale.items||[]).length"><td colspan="5"><div class="empty">No sale items.</div></td></tr></tbody></table></div></div></div><div v-else class="empty">Loading sale...</div></template>
<script setup lang="ts">import {formatDate as formatDisplayDate} from '../../utils/date';import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import StatusBadge from '../../components/StatusBadge.vue';const route=useRoute(),sale=ref<any>(null),{ask:confirm}=useConfirm(),toast=useToast();function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){sale.value=(await api.get(`/sales/${route.params.id}`)).data}async function voidSale(){if(!(await confirm({title:'Void sale?',message:`${sale.value.sale_number} will be voided, stock restored where applicable, and the related invoice will be affected. This action cannot be undone.`,confirmText:'Void sale',danger:true})))return;try{await api.delete(`/sales/${sale.value.id}`);toast.success('Sale voided',`${sale.value.sale_number} was voided successfully.`);await load()}catch(e){toast.error('Action failed',apiError(e))}}onMounted(load)</script>
